import type { ResolvedPos } from './../tiptap/pm/model.js';
import type { Selection } from './../tiptap/pm/state.js';

/**
 * Matches the public API of RicosCellSelection without importing it.
 */
export interface CellSelectionLike extends Selection {
  cellPositions: Set<number>;
  $anchorCell: ResolvedPos;
  $headCell: ResolvedPos;
}

/**
 * Type guard to check if a selection is a table cell selection using duck typing.
 * This avoids importing the RicosCellSelection class directly from the table plugin.
 */
export const isCellSelection = (selection: Selection): selection is CellSelectionLike => {
  return (
    selection !== null &&
    'cellPositions' in selection &&
    '$anchorCell' in selection &&
    '$headCell' in selection
  );
};
