import type { RicosPalette } from './../ricos-types/index.js';

const THEME_COLOR_SLOTS = ['1', '2', '3', '4', '5', '6', '7', '8', '9'] as const;

type ThemeColorSlot = (typeof THEME_COLOR_SLOTS)[number];
type ThemeColorBaseToken = `$theme-color-${ThemeColorSlot}`;
export type ThemeColorToken = ThemeColorBaseToken | `${ThemeColorBaseToken}-${number}`;

type PaletteField = keyof Omit<RicosPalette, 'format'>;

export const THEME_COLOR_SLOT_MAP: Record<ThemeColorSlot, PaletteField> = {
  '1': 'bgColor',
  '2': 'textColor',
  '3': 'accent1',
  '4': 'accent2',
  '5': 'accent3',
  '6': 'accent4',
  '7': 'shade1',
  '8': 'shade2',
  '9': 'shade3',
};

type ParsedThemeColorToken = {
  slot: ThemeColorSlot;
  opacity: number;
  baseToken: ThemeColorBaseToken;
};

const THEME_COLOR_TOKEN_REGEXP = /^\$theme-color-([1-9])(?:-(100|[1-9]\d|[0-9]))?$/;
const HEX_COLOR_WITH_OPTIONAL_ALPHA_RE = /^#([0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i;

/**
 * Use this when a plugin renders a color from document data.
 *
 * Call it for every plugin color field before using that value in the DOM:
 * React `style`, CSS variables, SVG attributes, gradients, Tiptap `renderHTML`,
 * and custom node views.
 *
 * Example:
 * `style={{ borderColor: resolveDocumentColorToCss(data.styles?.borderColor) }}`
 *
 * Why: theme tokens must stay connected to the active theme while rendering.
 * `$theme-color-2` becomes `var(--ricos-theme-color-2)`.
 * `$theme-color-2-50` becomes `rgba(var(--ricos-theme-color-2-tuple), 0.5)`.
 *
 * Hex colors are returned unchanged, so it is safe to run all document colors
 * through this on the render path.
 */
export function resolveDocumentColorToCss(color: string | undefined): string | undefined {
  if (!color) {
    return undefined;
  }
  const token = parseThemeColorToken(color);
  if (!token) {
    return color;
  }

  if (token.opacity === 100) {
    return themeColorTokenToCssVar(token.baseToken);
  }

  const tupleVar = themeColorTokenToCssVar(token.baseToken, 'rgbTuple');
  return `rgba(${tupleVar}, ${token.opacity / 100})`;
}

/**
 * Use this when code needs a fixed hex color.
 *
 * Good uses: color-picker display, static export, screenshots, or an API/UI that
 * cannot use CSS variables. Pass the current `theme.colorPalette` so the token
 * can be resolved to the matching palette color.
 *
 * Example:
 * `const displayColor = resolveDocumentColorToHex(documentColor, theme.colorPalette)`
 *
 * Do not use this for normal plugin rendering. It freezes the current theme
 * color as hex, so the rendered content will not update when the theme changes.
 * Use `resolveDocumentColorToCss` for viewer/editor DOM styles.
 */
export function resolveDocumentColorToHex(
  color: string | undefined,
  palette: RicosPalette
): string | undefined {
  if (!color) {
    return undefined;
  }
  if (!isThemeColorToken(color)) {
    return color;
  }
  return themeColorTokenToHex(color, palette) ?? color;
}

/**
 * Lower-level helpers used by shared color controls, validation, and theme CSS generation.
 */
export function isThemeColorToken(value: string | undefined | null): value is ThemeColorToken {
  return !!parseThemeColorToken(value);
}

export function stripThemeColorTokenOpacity(token: ThemeColorToken): ThemeColorBaseToken {
  return parseThemeColorToken(token)?.baseToken ?? (token as ThemeColorBaseToken);
}

export function getThemeColorTokenOpacity(token: ThemeColorToken): number {
  return parseThemeColorToken(token)?.opacity ?? 100;
}

export function setThemeColorTokenOpacity(
  token: ThemeColorToken,
  opacity: number
): ThemeColorToken {
  const parsed = parseThemeColorToken(token);
  if (!parsed) {
    return token;
  }

  const normalizedOpacity = Math.max(0, Math.min(100, Math.round(opacity)));
  return normalizedOpacity === 100
    ? parsed.baseToken
    : (`${parsed.baseToken}-${normalizedOpacity}` as ThemeColorToken);
}

export function themeColorTokenToCssVar(
  token: ThemeColorToken,
  format?: 'color' | 'rgbTuple'
): string {
  const baseToken = stripThemeColorTokenOpacity(token);
  const varName = `--ricos-${baseToken.slice(1)}`;
  return format === 'rgbTuple' ? `var(${varName}-tuple)` : `var(${varName})`;
}

export function themeColorTokenToHex(
  token: ThemeColorToken,
  palette: RicosPalette
): string | undefined {
  const parsed = parseThemeColorToken(token);
  if (!parsed) {
    return undefined;
  }

  const field = THEME_COLOR_SLOT_MAP[parsed.slot];
  const value = field && palette[field];
  if (!value) {
    return undefined;
  }

  const hex = palette.format === 'rgbTuple' ? rgbTupleToHex(value) : value;
  return applyOpacityToHexColor(hex, parsed.opacity);
}

function parseThemeColorToken(value: string | undefined | null): ParsedThemeColorToken | undefined {
  if (typeof value !== 'string') {
    return undefined;
  }

  const match = value.match(THEME_COLOR_TOKEN_REGEXP);
  if (!match) {
    return undefined;
  }

  const slot = match[1] as ThemeColorSlot;
  const opacity = match[2] ? Number(match[2]) : 100;

  return {
    slot,
    opacity,
    baseToken: `$theme-color-${slot}` as ThemeColorBaseToken,
  };
}

function rgbTupleToHex(tuple: string): string {
  const parts = tuple.split(',').map(s => parseInt(s.trim(), 10));
  return (
    '#' +
    parts
      .slice(0, 3)
      .map(n => n.toString(16).padStart(2, '0'))
      .join('')
  );
}

function applyOpacityToHexColor(color: string, opacity: number): string {
  if (opacity === 100) {
    return color;
  }

  const parsedHex = parseHexColor(color);
  if (!parsedHex) {
    return color;
  }

  const alpha = Math.round((opacity / 100) * 255)
    .toString(16)
    .padStart(2, '0')
    .toUpperCase();

  return `${parsedHex.baseHex}${alpha}`;
}

function parseHexColor(color: string): { baseHex: string; opacity: number } | undefined {
  const normalized = color.trim();
  const match = normalized.match(HEX_COLOR_WITH_OPTIONAL_ALPHA_RE);
  if (!match) {
    return undefined;
  }

  const digits = match[1];
  if (digits.length === 3 || digits.length === 4) {
    const expanded = digits
      .split('')
      .map(char => char + char)
      .join('');
    const baseHex = `#${expanded.slice(0, 6)}`;
    const alphaHex = expanded.slice(6, 8);
    return {
      baseHex,
      opacity: alphaHex ? Math.round((parseInt(alphaHex, 16) / 255) * 100) : 100,
    };
  }

  return {
    baseHex: `#${digits.slice(0, 6)}`,
    opacity: digits.length === 8 ? Math.round((parseInt(digits.slice(6, 8), 16) / 255) * 100) : 100,
  };
}
