// Divider attrs are derived per `DividerData` union member so the schema stays the single source
// of truth (a line style added there flows in automatically) and narrowing `lineStyle` still
// narrows `styles`. Every divider has a `lineStyle`, so the discriminant stays non-nullable; the
// other fields follow the PM attrs convention of always-present-but-null-when-unset.
type PmDividerAttrs<D = DividerData> = D extends DividerData
  ? { id: string; animation?: Animation | null } & {
      [K in keyof Required<Omit<D, 'animation'>>]: K extends 'lineStyle'
        ? D[K]
        : Exclude<D[K], undefined> | null;
    }
  : never;

export type PmDividerNode = {
  type: typeof PmNodeType.DIVIDER;
  attrs: PmDividerAttrs;
  content?: PmNode[];
};

