type PmHtmlNodeState =
  | {
      status: 'INITIAL';
      prompt?: PromptState;
    }
  | {
      status: 'SUCCESS';
      prompt?: PromptState;
    }
  | {
      status: 'LOADING';
      prompt: PromptState;
      requestId: string;
    }
  | {
      status: 'ERROR';
      prompt: PromptState;
      error: string;
    };

type PromptState = {
  text: string;
  selectedWidgetTypeId?: string;
  fileRefs: Attachment[];
};

export type Attachment =
  | {
      id: string;
      status: 'ok';
      file: {
        name: string;
        type: FileType;
        url: string;
      };
    }
  | {
      id: string;
      status: 'loading';
      file: {
        name: string;
        type: FileType;
      };
    }
  | {
      id: string;
      status: 'error';
      file: {
        name: string;
        type: FileType;
      };
      error: string;
    };

type FileType = 'png' | 'jpg' | 'jpeg' | 'csv' | 'text' | 'pdf';

