// Flat editor-side divider: the PM node carries every customization property
// regardless of shape; converting back to LayoutData narrows to the per-shape
// LayoutData_SectionDivider variant, dropping properties the shape doesn't
// support. Every union variant is assignable to this type.
export type PmSectionDivider = {
  type: LayoutData_SectionDividerShape;
  color?: string;
  height?: number;
  offsetX?: number;
  flipped?: boolean;
  layers?: LayoutData_SectionDividerLayers;
};

