import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { Resolver } from './../../ricos-types/index.js';

export const isHeaderTwoOrThreeSelected: Resolver<boolean> = content => {
  if (
    Array.isArray(content) &&
    content.length > 0 &&
    content[0].type.name !== Node_Type.PARAGRAPH
  ) {
    const headingLevel = content[0].attrs?.level;
    return headingLevel === 2 || headingLevel === 3;
  }
  return false;
};
