/**
 * Resolves only the plugins that the consumer configured.
 * Returns a pluginsMap containing only the requested plugin creators.
 */
export const resolvePlugins = async (
  pluginTypes: PluginName[]
): Promise<Partial<Record<PluginName, EditorPluginCreator>>> => {
  const entries = await Promise.all(
    pluginTypes
      .filter(type => dynamicPluginsMap[type])
      .map(async type => {
        const loader = dynamicPluginsMap[type]!;
        const creator = await loader();
        return [type, typeof creator === 'function' ? creator : (creator as any).default] as const;
      })
  );
  return Object.fromEntries(entries);
};
