import type { Editor } from './../tiptap/core/index.js';
import type { Node } from './../tiptap/pm/model.js';

export const getSelectedNodes = (editor: Editor) => {
  const selection = editor.state.selection;
  const nodes: Node[] = [];
  editor.state.doc.nodesBetween(selection.from, selection.to, (node: Node) => {
    nodes.push(node);
  });

  return nodes;
};
