import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { ResolvedPos } from './../../tiptap/pm/model.js';
import type { EditorState } from './../../tiptap/pm/state.js';

type CheckboxListItemAtPos = {
  checked: boolean;
};

// Strikethrough is disabled inside checked checkbox list items; everywhere else
// (unchecked items and non-checkbox content) it stays enabled.
const StrikethroughState = {
  Enabled: 'enabled',
  Disabled: 'disabled',
} as const;

type StrikethroughState = (typeof StrikethroughState)[keyof typeof StrikethroughState];

const getInnermostCheckboxListItemAtPos = ($pos: ResolvedPos): CheckboxListItemAtPos | null => {
  for (let depth = $pos.depth; depth > 0; depth--) {
    const node = $pos.node(depth);

    if (node.type.name !== Node_Type.LIST_ITEM) {
      continue;
    }

    const parent = $pos.node(depth - 1);

    if (parent.type.name === Node_Type.CHECKBOX_LIST) {
      return { checked: node.attrs.checked === true };
    }
  }

  return null;
};

const getStrikethroughStateAtPosition = ($pos: ResolvedPos): StrikethroughState =>
  getInnermostCheckboxListItemAtPos($pos)?.checked
    ? StrikethroughState.Disabled
    : StrikethroughState.Enabled;

const collectStrikethroughStates = (state: EditorState): StrikethroughState[] => {
  const { from, to } = state.selection;

  if (from === to) {
    return [getStrikethroughStateAtPosition(state.doc.resolve(from))];
  }

  const states: StrikethroughState[] = [];

  state.doc.nodesBetween(from, to, (node, pos) => {
    if (!node.isText) {
      return;
    }

    const textFrom = Math.max(from, pos);
    const textTo = Math.min(to, pos + node.nodeSize);

    states.push(getStrikethroughStateAtPosition(state.doc.resolve(textFrom)));

    if (textTo > textFrom + 1) {
      states.push(getStrikethroughStateAtPosition(state.doc.resolve(textTo - 1)));
    }
  });

  return states;
};

export const isStrikethroughBlockedByCheckboxListSelection = (state: EditorState): boolean => {
  const states = collectStrikethroughStates(state);

  return states.length > 0 && states.every(s => s === StrikethroughState.Disabled);
};
