import type { ValueOf } from './../ts-utils/value-of.js';

import type { ItemsResponseBody } from './serverless-types/serverless-types.js';

export type {
  BaseUrlResponseBody as BaseUrlResponse,
  SitePagesItem,
} from './serverless-types/serverless-types.js';

export const sitePagesPageType = {
  blogPost: 'blogPost',
  staticPage: 'staticPage',
  dynamicPage: 'dynamicPage',
  storeProduct: 'storeProduct',
  storeCatalog: 'storeCatalog',
} as const;

export type SitePagesDropdownOption = ValueOf<typeof sitePagesPageType>;

export type SitePagesPageType = SitePagesDropdownOption | 'dynamicItemPage';

export type FetchSitePagesParams = {
  query?: string;
  itemPagePrefix?: string;
  paging?: {
    cursor?: string;
    limit?: number;
  };
};

export type FetchSitePages = (
  pageType: SitePagesPageType,
  params: FetchSitePagesParams
) => Promise<ItemsResponseBody>;
