import type { Resolver } from './../../ricos-types/index.js';

export const getLineSpacingAfterSelection: Resolver<string | undefined> = (
  content,
  _services,
  _editor
) => {
  if (Array.isArray(content) && content.length > 0) {
    const lastWithPadding = content
      .filter(node => {
        if (!node?.attrs) {
          return false;
        }
        const { style, styleDefaults } = node.attrs;
        return style?.paddingBottom || styleDefaults?.paddingBottom;
      })
      .pop();

    return (
      lastWithPadding?.attrs.style?.paddingBottom ??
      lastWithPadding?.attrs.styleDefaults?.paddingBottom
    );
  }
};
