import type { FocusTrap as ElementFocusTrap, Options as FocusTrapOptions } from 'focus-trap';
import { createFocusTrap } from 'focus-trap';
import type { PropsWithChildren } from 'react';
import React from 'react';

import { FOCUSABLE_SELECTOR } from './../focusable-selector.js';
import { keys } from './../ts-utils/keys.js';

const checkedProps = ['active', 'paused', 'tag', 'focusTrapOptions', '_createFocusTrap'];

/**
 * Ceiling on how long to wait for a lazily-rendered panel, not an expected
 * duration: a trap whose content genuinely holds nothing focusable must still
 * end up active.
 */
const FOCUSABLE_CONTENT_TIMEOUT_MS = 1500;

const hasFocusableContent = (container: HTMLElement) =>
  !!container.querySelector('[data-autofocus]') || !!container.querySelector(FOCUSABLE_SELECTOR);

type FocusTrapProps = {
  active?: boolean;
  tag: string;
  paused?: boolean;
  focusTrapOptions?: FocusTrapOptions;
  _createFocusTrap: typeof createFocusTrap;
};

export class FocusTrap extends React.Component<PropsWithChildren<FocusTrapProps>> {
  static defaultProps = {
    active: true,
    tag: 'div',
    paused: false,
    focusTrapOptions: {},
    _createFocusTrap: createFocusTrap,
  };

  node!: HTMLElement;

  focusTrap!: ElementFocusTrap;

  /** Torn down on unmount, so a modal closed mid-wait leaves nothing observing. */
  focusableWaitCleanups: (() => void)[] = [];

  componentDidMount() {
    const options = this.getResolvedFocusTrapOptions();
    this.focusTrap = this.props._createFocusTrap(this.node, options);
    if (!this.node.firstElementChild?.hasAttribute('nofocus')) {
      if (this.props.active) {
        this.focusTrap.activate();
      }
      if (this.props.paused) {
        this.focusTrap.pause();
      }
    }
  }

  getResolvedFocusTrapOptions(): FocusTrapOptions | undefined {
    const options = this.props.focusTrapOptions;

    return {
      ...options,
      // If no initialFocus specified, look for [data-autofocus] within the trap container
      ...(!options?.initialFocus && {
        initialFocus: () => {
          const autofocusElement = this.node.querySelector<HTMLElement>('[data-autofocus]');
          return autofocusElement || undefined;
        },
      }),
      // `initialFocus: false` is an explicit opt-out of taking focus at all, so
      // there is nothing to wait for.
      ...(!options?.checkCanFocusTrap &&
        options?.initialFocus !== false && {
          checkCanFocusTrap: this.waitForFocusableContent,
        }),
    };
  }

  /**
   * `focus-trap` reads its tabbables — and so picks its initial-focus target —
   * the moment it activates. Panels that arrive through `React.lazy` activate the
   * trap while Suspense is still showing a fallback with nothing focusable in it,
   * so the trap finds no candidate and falls back to `fallbackFocus`: the trigger
   * the user just left. Nothing re-runs initial focus once the chunk lands, which
   * is why a dropdown opened by keyboard only took focus from its second open on.
   *
   * `checkCanFocusTrap` is focus-trap's hook for precisely this — it exists for
   * dialogs that fade in. While the returned promise is pending, focus-trap
   * defers the tabbable scan and the initial focus; it activates on either
   * settlement, so the timeout below can never strand the trap inactive.
   */
  waitForFocusableContent = (containers: (HTMLElement | SVGElement)[]): Promise<void> =>
    Promise.all(
      containers.map(
        container =>
          new Promise<void>(resolve => {
            const element = container as HTMLElement;

            if (hasFocusableContent(element)) {
              resolve();
              return;
            }

            let timer: ReturnType<typeof setTimeout>;

            const settle = () => {
              clearTimeout(timer);
              observer.disconnect();
              resolve();
            };

            const observer = new MutationObserver(() => {
              if (hasFocusableContent(element)) {
                settle();
              }
            });

            timer = setTimeout(settle, FOCUSABLE_CONTENT_TIMEOUT_MS);
            observer.observe(element, { childList: true, subtree: true });
            this.focusableWaitCleanups.push(settle);
          })
      )
    ).then(() => undefined);

  componentDidUpdate(prevProps: FocusTrapProps) {
    if (prevProps.active && !this.props.active) {
      this.focusTrap.deactivate();
    } else if (!prevProps.active && this.props.active) {
      this.focusTrap.activate();
    }

    if (prevProps.paused && !this.props.paused) {
      this.focusTrap.unpause();
    } else if (!prevProps.paused && this.props.paused) {
      this.focusTrap.pause();
    }
  }

  componentWillUnmount() {
    this.focusableWaitCleanups.forEach(cleanup => cleanup());
    this.focusableWaitCleanups = [];
    this.focusTrap.deactivate();
  }

  setNode = (el: $TSFixMe) => (this.node = el);

  render() {
    const elementProps = keys(this.props)
      .filter(
        prop =>
          Object.prototype.hasOwnProperty.call(this.props, prop) && !checkedProps.includes(prop)
      )
      .reduce(
        (resultProps, prop) => ({
          ...resultProps,
          [prop]: this.props[prop],
        }),
        {
          ref: this.setNode,
        }
      );

    return React.createElement(this.props.tag, elementProps, this.props.children);
  }
}
