import { WixDesignSystemIconThemeProvider } from '@wix/design-system';
import { IconThemeProvider } from '@wix/wix-ui-icons-common/core';
import React from 'react';

import type { Environment } from './../ricos-types/index.js';

type RicosIconThemeProviderProps = React.PropsWithChildren<{
  environment?: Environment;
}>;

/**
 * Selects the icon variant that theme-aware icons resolve to.
 *
 * `IconThemeProvider` drives which CDN variant ricos' own lazy icons fetch;
 * `WixDesignSystemIconThemeProvider` swaps the icons WDS components render
 * internally (close buttons, input suffixes, accordion carets…) for their
 * theme-aware twins. Both are plain context providers, so they render no DOM
 * and reach portalled toolbars and modals along with the rest of the tree.
 *
 * Only `wixel` opts in. Ricos is a shared bundle: in the other environments the
 * host editor owns the icon theme and may already have mounted a provider of its
 * own, so declaring a theme here would override the host rather than follow it.
 *
 * Not mounted by the viewer — no theme-aware icon is reachable from the viewer's
 * entry point, and mounting this would pull `@wix/design-system` into the live-site
 * bundle. Wixel's viewer surfaces get the theme from www-ricos' own provider.
 */
export const RicosIconThemeProvider: React.FC<RicosIconThemeProviderProps> = ({
  environment,
  children,
}) => {
  if (environment !== 'wixel') {
    return <>{children}</>;
  }

  return (
    <IconThemeProvider theme="odeditor">
      <WixDesignSystemIconThemeProvider>{children}</WixDesignSystemIconThemeProvider>
    </IconThemeProvider>
  );
};
