import type { IEditorQuery } from './../../ricos-content-query/index.js';
import type { Resolver } from './../../ricos-types/index.js';

export const getLineSpacingInSelection: Resolver<string | undefined> = (
  _content,
  { getEditorQuery },
  _editor
) => {
  const editorQuery: IEditorQuery = getEditorQuery();
  const activeTextStyles = editorQuery.query.activeTextStyles('lineHeight');

  if (
    activeTextStyles.length > 0 &&
    activeTextStyles.every(
      (lineHeight: $TSFixMe, _index: $TSFixMe, arr: $TSFixMe) => lineHeight === arr[0]
    )
  ) {
    return activeTextStyles[0].toString();
  } else {
    return undefined;
  }
};
