import type { Resolver } from './../../ricos-types/index.js';

export const getLineSpacingBeforeSelection: Resolver<string | undefined> = (
  content,
  _services,
  _editor
) => {
  if (!Array.isArray(content) || content.length === 0) {
    return undefined;
  }

  const node = content.find(node => {
    if (!node?.attrs) {
      return;
    }
    const { style, styleDefaults } = node.attrs;
    return style?.paddingTop || styleDefaults?.paddingTop;
  });

  return node?.attrs?.style?.paddingTop ?? node?.attrs?.styleDefaults?.paddingTop;
};
