import { useMemo } from 'react';
import { useSyncExternalStore } from 'use-sync-external-store/shim';

import { getResolvedPaletteColors } from './../ricos-styles/themeStrategy/generators/palette.js';
import type { ColorPaletteManager, Gradient } from './../ricos-types/color-palette-types.js';
import type { RicosPalette, RicosTheme } from './../ricos-types/theme-types.js';
import { resolveColorsPalette } from './../wix-rich-content-common/index.js';

import { areGradientsEqual } from './are-gradients-equal.js';
import { THEME_COLOR_SLOT_MAP, type ThemeColorToken } from './theme-color-token.js';

export type ThemeColorSwatch = {
  /** Display hex (or `rgb(...)` for `rgbTuple` palettes) used to render the swatch. */
  hex: string;
  /** Present only for `theme.colorPalette` slots; clicking the swatch saves this token. */
  token?: ThemeColorToken;
};

const DEFAULT_PALETTE_SIZE = 58; // 6×10 grid - 1 add button - 1 empty slot
const COLORS_KEY = 'ricos/custom-colors';
const GRADIENTS_KEY = 'ricos/custom-gradients';

const getCustomColors = (
  colorManager: ColorPaletteManager | undefined,
  legacyGetColors?: () => string[]
) => colorManager?.colors ?? legacyGetColors?.() ?? readStorage<string[]>(COLORS_KEY, []);

const isSameColor = (left: string, right: string): boolean =>
  left.toUpperCase() === right.toUpperCase();

const isNonBlank = (value: string | undefined): value is string =>
  typeof value === 'string' && value.trim().length > 0;

// First six slots of THEME_COLOR_SLOT_MAP. The remaining `shade1..3` slots
// exist as theme tokens for plugin styles but are not surfaced as swatches.
const VISIBLE_SWATCH_TOKENS: [keyof Omit<RicosPalette, 'format'>, ThemeColorToken][] = (
  Object.entries(THEME_COLOR_SLOT_MAP) as [string, keyof Omit<RicosPalette, 'format'>][]
)
  .slice(0, 6)
  .map(([slot, field]) => [field, `$theme-color-${slot}` as ThemeColorToken]);

const dedupeByHex = <T extends { hex: string }>(swatches: T[]): T[] => {
  const seen = new Set<string>();
  return swatches.filter(s => {
    const key = s.hex.toUpperCase();
    if (seen.has(key)) {
      return false;
    }
    seen.add(key);
    return true;
  });
};

export const getResolvedCustomColors = (
  colorManager: ColorPaletteManager | undefined,
  currentColor?: string,
  legacyGetColors?: () => string[],
  paletteSize = DEFAULT_PALETTE_SIZE
): string[] => {
  return resolveColorsPalette(
    getCustomColors(colorManager, legacyGetColors),
    currentColor,
    paletteSize
  );
};

export const resolveThemeColorsPalette = (
  theme: Pick<RicosTheme, 'colorPalette' | 'palette'>,
  fallbackColors: string[] = []
): ThemeColorSwatch[] => {
  // Integrator-supplied colors override the theme palette and never carry tokens.
  const configSwatches = fallbackColors.filter(isNonBlank).map(hex => ({ hex }));
  if (configSwatches.length > 0) {
    return dedupeByHex(configSwatches);
  }

  const { colorPalette } = theme;
  if (colorPalette) {
    const swatches: ThemeColorSwatch[] = [];
    for (const [field, token] of VISIBLE_SWATCH_TOKENS) {
      const value = colorPalette[field];
      if (isNonBlank(value)) {
        swatches.push({
          hex: colorPalette.format === 'rgbTuple' ? `rgb(${value})` : value,
          token,
        });
      }
    }
    return dedupeByHex(swatches);
  }

  // Legacy `theme.palette` predates the token system so its colors are emitted
  // without a token and behave like a saved-color hex on click.
  return dedupeByHex(
    Object.values(getResolvedPaletteColors(theme.palette))
      .filter(isNonBlank)
      .map(hex => ({ hex }))
  );
};

export const useResolvedCustomColors = (
  colorManager: ColorPaletteManager | undefined,
  legacyGetColors?: () => string[],
  paletteSize = DEFAULT_PALETTE_SIZE
): string[] => {
  const storageVersion = useStorageVersion();
  return useMemo(() => {
    return getResolvedCustomColors(colorManager, undefined, legacyGetColors, paletteSize);
  }, [colorManager?.colors, legacyGetColors, paletteSize, storageVersion]);
};

export const handleColorAdded = (
  color: string,
  colorManager: ColorPaletteManager | undefined,
  legacyOnColorAdded?: (color: string) => void | string[]
): void => {
  if (colorManager) {
    colorManager.setColors([...colorManager.colors, color]);
  } else if (legacyOnColorAdded) {
    legacyOnColorAdded(color);
    // Notify storage-version listeners so that useResolvedCustomColors re-reads
    // getUserColors() and the color picker reflects the change immediately.
    notify();
  } else {
    writeStorage(COLORS_KEY, [...readStorage<string[]>(COLORS_KEY, []), color]);
  }
};

export const handleColorDeleted = (
  color: string,
  colorManager: ColorPaletteManager | undefined
): void => {
  if (colorManager) {
    colorManager.setColors(
      colorManager.colors.filter(savedColor => !isSameColor(savedColor, color))
    );
  } else {
    writeStorage(
      COLORS_KEY,
      readStorage<string[]>(COLORS_KEY, []).filter(savedColor => !isSameColor(savedColor, color))
    );
  }
};

export const useResolvedCustomGradients = (
  colorManager: ColorPaletteManager | undefined
): Gradient[] => {
  const storageVersion = useStorageVersion();
  return useMemo(() => {
    return colorManager?.gradients ?? readStorage<Gradient[]>(GRADIENTS_KEY, []);
  }, [colorManager?.gradients, storageVersion]);
};

export const handleGradientAdded = (
  gradient: Gradient,
  colorManager: ColorPaletteManager | undefined
): void => {
  if (colorManager?.setGradients) {
    colorManager.setGradients([...(colorManager.gradients ?? []), gradient]);
  } else {
    writeStorage(GRADIENTS_KEY, [...readStorage<Gradient[]>(GRADIENTS_KEY, []), gradient]);
  }
};

export const handleGradientDeleted = (
  gradient: Gradient,
  colorManager: ColorPaletteManager | undefined
): void => {
  if (colorManager?.setGradients) {
    colorManager.setGradients(
      (colorManager.gradients ?? []).filter(
        savedGradient => !areGradientsEqual(savedGradient, gradient)
      )
    );
  } else {
    writeStorage(
      GRADIENTS_KEY,
      readStorage<Gradient[]>(GRADIENTS_KEY, []).filter(
        savedGradient => !areGradientsEqual(savedGradient, gradient)
      )
    );
  }
};

// localStorage persistence with reactive subscriptions
let version = 0;
const listeners = new Set<() => void>();
const notify = () => {
  version++;
  listeners.forEach(listener => listener());
};
const readStorage = <T>(key: string, fallback: T): T => {
  try {
    return JSON.parse(localStorage.getItem(key)!) ?? fallback;
  } catch {
    return fallback;
  }
};
const writeStorage = (key: string, value: unknown) => {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch {}
  notify();
};
const useStorageVersion = () =>
  useSyncExternalStore(
    listener => {
      listeners.add(listener);
      return () => void listeners.delete(listener);
    },
    () => version
  );
