const UNSAFE_KEYS = ['__proto__', 'constructor', 'prototype'];

// Mirrors the lodash.merge behavior our call sites rely on: recursively merges
// plain objects and arrays (index-wise), skips `undefined` source values so they
// never erase defaults, and assigns everything else (functions, class instances)
// by reference.
const isMergeable = (value: unknown): value is Record<string, unknown> => {
  if (Array.isArray(value)) {
    return true;
  }
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  // Plain data objects, including null-prototype ones. ProseMirror builds
  // node/mark attrs with Object.create(null), so restricting to Object.prototype
  // would make deepMerge skip them entirely and drop all their keys.
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
};

const mergeInto = (target: Record<string, unknown>, source: Record<string, unknown>) => {
  for (const key of Object.keys(source)) {
    if (UNSAFE_KEYS.includes(key)) {
      continue;
    }
    const sourceValue = source[key];
    if (sourceValue === undefined) {
      continue;
    }
    const targetValue = target[key];
    if (isMergeable(sourceValue)) {
      if (isMergeable(targetValue) && Array.isArray(targetValue) === Array.isArray(sourceValue)) {
        mergeInto(targetValue, sourceValue as Record<string, unknown>);
      } else {
        const fresh: Record<string, unknown> = Array.isArray(sourceValue) ? ([] as never) : {};
        mergeInto(fresh, sourceValue as Record<string, unknown>);
        target[key] = fresh;
      }
    } else {
      target[key] = sourceValue;
    }
  }
};

// Overloads mirror lodash.merge's return type (intersection of target and
// sources) so merging into `{}` still yields the source shape.
export function deepMerge<A extends object, B>(target: A, b: B): A & B;
export function deepMerge<A extends object, B, C>(target: A, b: B, c: C): A & B & C;
export function deepMerge<A extends object, B, C, D>(target: A, b: B, c: C, d: D): A & B & C & D;
export function deepMerge<A extends object, B, C, D, E>(
  target: A,
  b: B,
  c: C,
  d: D,
  e: E
): A & B & C & D & E;
export function deepMerge<T extends object>(target: T, ...sources: unknown[]): T;
export function deepMerge<T extends object>(target: T, ...sources: unknown[]): T {
  for (const source of sources) {
    if (isMergeable(source)) {
      mergeInto(target as Record<string, unknown>, source);
    }
  }
  return target;
}
